  a6:  { modes: ["agentless", "agent"], net: { rules: 2,  proto: "仅 CONNECT" } },
  a7:  { modes: ["agent"], net: { rules: 16, proto: "仅 CONNECT", wl: ["10.10.1.20:22"] } },
