  if (ctx.closure === "mode" && !inClosure(n.attr, ctx.mode)) { out.push({ level: "err", text: `「${a.label}」不在当前形态（${MODE_LABEL[ctx.mode]}）的属性闭包内，越界条件将静默失效` }); return out; }
