    FG.sel.clear();
    S.designer = null;        /* 清理设计器上下文，避免 renderAsp 被继续分派到「设置访问要求」页 */
    S.sel = null;
    const carry = R.kind === "attr" ? authCarryNote(R.cond) : "";
