function cleanTree(n) { const o = {}; ["t", "op", "attr", "v", "inc", "q", "mode", "ref"].forEach(k => { if (n[k] !== undefined) o[k] = n[k]; }); if (n.t === "g") { o.ch = (n.ch || []).map(cleanTree); delete o.attr; } return o; }

